    public static function key(string $source):string{return'invoice_bank_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array
    {
        $en=explode('-',$locale,2)[0]==='en';$out=[];
        foreach(self::ENGLISH as$source=>$translation)$out[self::key($source)]=$en?$translation:$source;return$out;
    }
    public static function text(string $source,array $messages):string
    {
        if(isset($messages[self::key($source)]))return$messages[self::key($source)];
        foreach(\Kulturhus\Verein\SettingsSchema::fields('bank')as$field)if(str_starts_with($source,$field[0].': '))return self::text($field[0],$messages).': '.self::text(substr($source,strlen($field[0])+2),$messages);
        if(preg_match('/\AIBAN für ([A-Z]{2}) muss ([0-9]{2}) Zeichen ohne Leerzeichen enthalten\.\z/D',$source,$parts))return strtr(self::text('IBAN für {country} muss {length} Zeichen ohne Leerzeichen enthalten.',$messages),['{country}'=>$parts[1],'{length}'=>$parts[2]]);
        if(preg_match('/\AIBAN für ([A-Z]{2}) darf nach Länderkennung und Prüfziffer nur Ziffern enthalten\.\z/D',$source,$parts))return strtr(self::text('IBAN für {country} darf nach Länderkennung und Prüfziffer nur Ziffern enthalten.',$messages),['{country}'=>$parts[1]]);
        if(preg_match('/\\AUrsprüngliche Teilbewegung ([0-9]+) öffnen\\z/D',$source,$parts))return strtr(self::text('Ursprüngliche Teilbewegung {number} öffnen',$messages),['{number}'=>$parts[1]]);
        return NumberingMessages::text($source,$messages);
    }
}
